  unsigned long version;
  void *backing;
} page_t;

int claim_fault(page_t *p){
  unsigned long v = p->version;
  return __atomic_compare_exchange_n(&p->version, &v, v+1, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}
```

